 const values={uSpread:.5,uLength:2.5,uFade:1,uSaturation:1,uPulsating:0,uNoise:0,uDistortion:0,uDensity:1,uSharpness:.3,uGlow:.25,uHaze:0,uAtmosphere:0,uIntensity:.7,uLight:0,uOpacity:.35};
 Object.entries(values).forEach(([k,v])=>gl.uniform1f(u[k],v));
 gl.uniform4f(u.uShadow,0,0,0,0);gl.uniform4fv(u.uPulses,new Float32Array(16));gl.uniform2f(u.uIntro,2.6,1);
